var e=`0165-pasta-alla-norma`;var i=`world-0165`;var n=`IT`;var o=`southern-europe`;var s=4;var r=56;var l={en:`Pasta alla Norma`,ua:`Паста алла Норма`};var g={en:`Sicilian pasta with tomato, basil and aubergine, finished with Pecorino instead of unavailable ricotta salata.`,ua:`Сицилійська паста з помідорами, базиліком і баклажанами, доповнена пекоріно замість відсутньої в каталозі рикоти салата.`};var u=[{en:`Cut the vegetables evenly and roast at 200°C for about 25 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 25 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:25,i:[[`eggplant`,500,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 18 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 18 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:18,i:[[`tomato-passata`,480,`g`],[`garlic`,3,`clove`],[`basil`,25,`g`]]},{en:`Cook the pasta in generously salted boiling water for about 10 minutes until al dente; reserve a cup of its starchy water.`,ua:`Варіть пасту в добре підсоленій киплячій воді приблизно 10 хвилин до стану аль денте; збережіть чашку крохмалистої води.`,t:[`pasta-boiling`],m:10,i:[[`rigatoni`,380,`g`],[`water`,1500,`ml`],[`table-salt`,9,`g`]]},{en:`Toss the rigatoni with the tomato sauce and roasted eggplant; finish with the salty grated Pecorino as a replacement for ricotta salata, which is absent from the catalog.`,ua:`Змішайте ригатоні з томатним соусом і запеченим баклажаном; додайте натертий солоний пекоріно замість рикоти салата, якої немає в каталозі.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pecorino-romano`,100,`g`]]}];var h={slug:e,id:i,country:`IT`,region:o,servings:4,minutes:56,title:l,text:g,steps:u};export{n as country,h as default,i as id,r as minutes,o as region,s as servings,e as slug,u as steps,g as text,l as title};